'use strict';
const apps=[
 {id:'chat',name:'Yamachat',icon:'yamachat.png',platform:'Windows · Web · Android · iOS PWA',status:'Existující aplikace',description:'Chat, komunity, hlasové hovory a streamování.',detail:'Zdrojový projekt a databázová struktura jsou ověřené. Stávající účet Yamachat zůstává základem společné identity. Integrované otevření v Portalu vyžaduje ještě test hovorů, streamování a relací. Živý web a oficiální stahovací stránka odpověděly HTTP 200. Samostatný web používá vlastní relaci; předání přihlášení z místního Portalu zatím není implementované.'},
 {id:'search',name:'YamaSearch',icon:'yamasearch.png',platform:'Windows · Android · iOS startovní PWA',status:'Společný účet ve Windows',description:'Samostatný prohlížeč. Windows podporuje volitelný účet Yamaportal.',detail:'Windows verze používá WPF a WebView2. Existují zdroje Android varianty. iOS PWA je startovní stránka otevírající weby externě, nemá vlastní prohlížečové jádro. Windows 0.3.22 přidává volitelný společný účet Yamaportal. Původní účet YamaSearch zůstává dostupný. Android a iOS tímto vydáním společný účet nezískávají. Základní prohlížení zůstane bez povinného účtu.'},
 {id:'help',name:'YamaHelp',icon:'yamahelp.png',platform:'Windows',status:'Existující aplikace',description:'Diagnostika, údržba a nástroje pro Windows.',detail:'Byly nalezeny místní WPF zdroje verze 1.0.86 a aktualizační mechanismus. Oficiální Installer a Portable odpověděly HTTP 200. Veřejný aktualizační zdroj uvádí 1.0.85, místní zdroje 1.0.86. Dostupnost souboru sama nepotvrzuje instalaci ani jeho integritu. Aplikace se bude spouštět samostatně a základní funkce nebudou vyžadovat účet.'},
 {id:'maker',name:'YamaMaker',symbol:'✎',platform:'Platformy zatím nepotvrzené',status:'Připravuje se',description:'Projekt pro tvorbu a úpravu obsahu.',detail:'V dostupných složkách zatím nebyla nalezena zdrojová implementace. Aplikace nemá v Portalu aktivní stažení ani spuštění. Rozsah a platformy doplníme podle skutečných zdrojů.'},
 {id:'view',name:'YamaView',symbol:'▣',platform:'Platformy zatím nepotvrzené',status:'Připravuje se',description:'Připravovaný projekt vzdáleného ovládání.',detail:'Nalezený klikací prototyp používá simulovaná zařízení a relace. Podklady pro RustDesk nejsou důkazem funkčního vzdáleného přístupu. Proto zatím nenabízíme připojení ani instalátor.'}
];
let availability=null;
const page=document.querySelector('#page');
const icon=a=>a.icon?`<img class="app-icon" src="assets/${a.icon}" alt="Logo ${a.name}">`:`<span class="app-icon placeholder" aria-hidden="true">${a.symbol}</span>`;
const primaryAction=a=>a.id==='chat'?'<a class="primary" href="#yamachat">Otevřít v Portalu →</a>':['search','help'].includes(a.id)?'<button class="primary" data-detail="'+a.id+'">Otevřít / stáhnout →</button>':'<span class="coming-soon">Připravuje se</span>';
const cards=()=>'<div class="apps">'+apps.map(a=>'<article class="card app-'+a.id+'"><div class="app-head">'+icon(a)+'<div><h3>'+a.name+'</h3><span class="platform">'+a.platform+'</span></div></div><p>'+a.description+'</p><div class="card-footer">'+primaryAction(a)+'<button class="card-options" data-detail="'+a.id+'" aria-label="Možnosti aplikace '+a.name+'">Možnosti a informace</button></div></article>').join('')+'</div>';
const names={stazeni:'Stažení Yamaportalu',consent:'Propojení YamaSearch',yamachat:'Yamachat',domu:'Domů',aplikace:'Aplikace',profil:'Můj profil',propojeni:'Propojení',nastaveni:'Nastavení',aktualizace:'Aktualizace'};
function renderPage(){const route=location.hash.slice(1)||'domu';const active=Object.hasOwn(names,route)?route:'domu';document.querySelectorAll('nav a').forEach(a=>{const selected=a.hash==='#'+active;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 page.hidden=active==='yamachat';if(active==='yamachat'){void YamaModuleHost.show();return;}YamaModuleHost.hide();
 if(active==='consent'){void YamaConsent.show();return;}
 if(active==='domu')page.innerHTML=`<div class="home"><section class="panel catalog"><div class="catalog-heading"><div><p class="eyebrow">VYBER SI APLIKACI</p><h2>Tvůj prostor. Tvoje aplikace.</h2><p class="muted">Spusť aplikaci v Portalu nebo si vyber samostatnou verzi.</p></div><a class="secondary" href="#profil">Můj Yama účet →</a></div>${cards()}</section><section class="portal-download-banner"><div><h2>Yamaportal pro tvé zařízení</h2><p>Windows aplikace nebo instalovatelný web na mobilu.</p></div><a class="primary" href="#stazeni">Stáhnout / nainstalovat →</a></section></div>`;
 if(active==='aplikace')page.innerHTML=`<section class="panel catalog"><h2>Všechny Yama aplikace</h2><p class="muted">Ověřené oficiální odkazy. Přihlašování a možnosti jednotlivých platforem se ověřují samostatně.</p>${cards()}</section>`;
 if(active==='stazeni'){page.innerHTML='<section class="panel page-content"><h2>Stáhnout Yamaportal</h2><div id="portal-download-list"><p>Ověřuji dostupné balíčky…</p></div>'+YamaPortalPWA.markup()+'</section>';void YamaDownloads.render();}
 if(active==='profil')page.innerHTML=YamaAccountUI.profilePage();
 if(active==='propojeni')page.innerHTML=YamaAccountUI.connections();
 if(active==='nastaveni')page.innerHTML=`<section class="panel page-content"><h2>Nastavení Yamaportalu</h2><p class="muted">Tyto volby fungují lokálně v tomto prohlížeči.</p><label class="settings-row"><span>Rozložení rozhraní</span><select id="layout"><option value="web">Horní navigace</option><option value="windows">Boční navigace</option></select></label><label class="settings-row"><span>Hustota zobrazení</span><select id="density"><option value="comfortable">Pohodlné</option><option value="compact">Kompaktní</option></select></label>${YamaPortalPWA.markup()}<div class="notice"><strong>Otevírání a zabezpečení aplikací</strong>Na počítači můžeš zvolit horní nebo boční navigaci. Mobil používá horní menu. Windows aplikaci stáhneš v sekci Stažení Yamaportalu.</div><button class="secondary" id="reset">Obnovit výchozí vzhled</button><p id="saved" role="status" class="caption"></p></section>`;
 if(active==='aktualizace')page.innerHTML=`<section class="panel page-content"><h2>Aktualizace</h2><p class="muted">Ověřeno ve zdrojích, nikoli ověřeno jako nejnovější dostupné stažení.</p><div class="rows"><article class="row"><h3>Yamachat</h3><p>Manifest hlavní větve uvádí Windows 1.0.128 a Android 1.1.0.798. Stahovací stránka zároveň obsahuje starší pevný Windows odkaz; dostupnost aktuálních balíčků je nutné ověřit.</p></article><article class="row"><h3>YamaSearch</h3><p>Hlavní větev od 18. 10. 2026 obsahuje Windows 0.3.21 s účtem. Propojení účtu s Portalem je samostatná etapa.</p></article><article class="row"><h3>YamaHelp</h3><p>Veřejný aktualizační zdroj při kontrole 19. 10. 2026 uváděl 1.0.85. Místní projekt uvádí 1.0.86; tato verze nebyla potvrzena jako veřejné vydání.</p></article><article class="row"><h3>Yamaportal, YamaMaker a YamaView</h3><p>V tomto preview nejsou dostupné nové instalační balíčky.</p></article></div></section>`;
 if(active==='nastaveni'){document.querySelector('#layout').value=prefs.mode;document.querySelector('#density').value=prefs.density;document.querySelector('#layout').onchange=e=>update({mode:e.target.value});document.querySelector('#density').onchange=e=>update({density:e.target.value});document.querySelector('#reset').onclick=()=>{update({mode:'web',density:'comfortable'});render();};}
}
function render(){try{renderPage();}catch{page.hidden=false;page.innerHTML='<section class="panel"><h2>Stránku se nepodařilo načíst</h2><p>Obnov stránku nebo se vrať na přehled aplikací.</p><a class="secondary" href="#domu">Přehled aplikací</a></section>';}}
let prefs={mode:'web',density:'comfortable'};try{const saved=JSON.parse(localStorage.getItem('yamaportal-preview-preferences'));if(saved&&['web','windows'].includes(saved.mode))prefs.mode=saved.mode;if(saved&&['comfortable','compact'].includes(saved.density))prefs.density=saved.density;}catch{}
function update(next){Object.assign(prefs,next);document.body.classList.toggle('windows',prefs.mode==='windows');document.body.classList.toggle('compact',prefs.density==='compact');document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===prefs.mode)));let message='Vzhled je uložený v tomto prohlížeči.';try{localStorage.setItem('yamaportal-preview-preferences',JSON.stringify(prefs));}catch{message='Vzhled se změnil. Prohlížeč nepovolil jeho uložení.';}const status=document.querySelector('#saved');if(status)status.textContent=message;const select=document.querySelector('#layout');if(select)select.value=prefs.mode;}
document.addEventListener('click',e=>{const mode=e.target.closest('[data-mode]');if(mode)update({mode:mode.dataset.mode});const route=e.target.closest('[data-route]');if(route)location.hash=route.dataset.route;const button=e.target.closest('[data-detail]');if(button){const a=apps.find(x=>x.id===button.dataset.detail);document.querySelector('#detail-content').innerHTML=`${icon(a)}<h2>${a.name}</h2><span class="pill">${a.status}</span><p>${a.detail}</p><p class="caption">${a.platform}</p>${YamaAppLinks.markup(availability,a.id)}`;document.querySelector('#detail').showModal();}if(e.target.closest('.close,.close-detail'))document.querySelector('#detail').close();});
if(new URL(location.href).searchParams.has('authorization_id'))location.hash='consent';
window.addEventListener('hashchange',render);update({});render();

document.addEventListener('yama-account-state',()=>{if(YamaAccountUI.shouldRender())render();});
window.addEventListener('hashchange',()=>YamaAccountUI.clearDirty());
void YamaAccountUI.init();





fetch('app-availability.json',{cache:'no-store'}).then(response=>response.ok?response.json():null).then(report=>{availability=report;if(['domu','aplikace','aktualizace',''].includes(location.hash.slice(1))&&YamaAccountUI.shouldRender())render();}).catch(()=>{});
document.addEventListener('yama-native-state',()=>{if(['domu','aplikace',''].includes(location.hash.slice(1)))render();});
